// The only entry point for the psychologist's advice (decision R-33).
//
// Screens call these functions and show whatever comes back. They never
// read an advice file or a server directly, so moving advice to the server
// in release 2 changes only this folder.
//
// Rules:
// - Advice is never generated by AI. Only texts from Yana's approved pool (R-8).
// - The public test build ships no paid advice at all: any file bundled into
//   the app can be read by anyone who opens the page code (R-33, rule 4).
//   Advice texts live only in the separate test build for Yana and testers (R-39).

import { selectAdvice } from './select.js';
import { POOL } from './pool.js';
import { dictionaryCode } from '../data/options.js';
import { sportGroup } from '../data/sports.js';

// On only in the build with advice (R-39): built with VITE_ADVICE=1 and pool.json.
// In the public build it stays off, so no advice is "remembered" as read
// while the person cannot see it (the variant circles would drift).
export const ADVICE_ENABLED = import.meta.env?.VITE_ADVICE === '1' && POOL !== null;
export { POOL };

// Earlier trainings of this person (all sports), oldest first.
const earlierThan = (entry, entries) =>
  entries
    .filter((e) => e.id !== entry.id && e.createdAt < entry.createdAt)
    .sort((a, b) => a.createdAt - b.createdAt);

// Returns the entry with `advicePick` (ids of advice pieces, R-38) when advice is on.
// The pick is saved with the training, so reopening it shows the same advice.
export function withAdvicePick(entry, diary, entries) {
  if (!ADVICE_ENABLED) return entry;
  const history = earlierThan(entry, entries)
    .map((e) => e.advicePick)
    .filter(Boolean);
  const pick = selectAdvice(
    { ...entry, emotions: (entry.emotions ?? []).map(dictionaryCode) },
    sportGroup(diary.code),
    history,
  );
  return { ...entry, advicePick: pick };
}

// Possible results:
//   { status: 'locked' }                    - paid feature, not available
//   { status: 'ok', advice: { id, text } }  - release 2, from the server
export async function getAdvice(entry) {
  // Test build: the entry is not used yet. Release 2 sends it to the server.
  void entry;
  return { status: 'locked' };
}
